func thoughtIcon(kind string) string {
	switch kind {
	case "reasoning":
		return "ti-bulb"
	case "search":
		return "ti-world-search"
	case "code":
		return "ti-code"
	case "read":
		return "ti-file-text"
	default:
		return "ti-point"
	}
}

