func kindColor(kind string) string {
	switch strings.ToLower(kind) {
	case "pdf":
		return "red"
	case "csv", "xlsx", "xls":
		return "green"
	case "md", "txt", "doc", "docx":
		return "blue"
	case "html", "url", "web":
		return "purple"
	}
	return "secondary"
}

